function evs = Bloch(D, wl, N, gamma, plotflag)
%% Formulates and solves the linear stability problem for a periodic steady state of the nonlocal Fisher-KPP equation.
% Based on code generated by Google Gemini

% D = Diffusion coefficient
% wl = Wavelength of the periodic pattern (L)
% N  = Number of grid points (must be an even integer)
% gamma - Bloch wavenumbers
% plotflag  - Plot if true
%
% evs - 2N x length(gamma) matrix of complex eigenvalues

if mod(N, 2) ~= 0
    error('Number of grid points N must be even for standard spectral methods.');
end

%% Construct periodic spectral differentiation matrices using toeplitz
% First derivative D1: Set Nyquist frequency to 0 to ensure exact real outputs
k = (2 * pi / wl) * [0:N/2-1, -N/2, -N/2+1:-1]';
k_D1 = k;
k_D1(N/2 + 1) = 0; 
c1 = real(ifft(1i * k_D1));
r1 = [c1(1); c1(end:-1:2)];
D1 = toeplitz(c1, r1); % Circulant matrix representing d/dx

% Second derivative D2
c2 = real(ifft(-k.^2));
r2 = [c2(1); c2(end:-1:2)];
D2 = toeplitz(c2, r2); % Circulant matrix representing d^2/dx^2

%% Find the periodic solution
L = periodic(N,wl,D,[],false);
u0 = exp(L([end 1:end-1])); u0 = u0(:); 

%% Convolution phi * u0 via FFT. 
phi_hat = sinc(k / (2 * pi)); 
u0_hat = fft(u0);
conv_phi_u0 = real(ifft(phi_hat .* u0_hat));
V = 1 - conv_phi_u0;

% Preallocate diagonal matrices for local multiplications
U0_mat = diag(u0); V_mat = diag(V); I_mat = eye(N);

%% Loop over Bloch wavenumbers to assemble and solve the problem
evs = zeros(2 * N, length(gamma));

for j = 1:length(gamma)
    disp(j)
    % The continuous convolution kernel shifted by the Bloch phase gamma
    S_gamma = sinc((gamma(j) + k) / (2 * pi));

    % Construct the circulant matrix for the nonlocal operator using toeplitz
    c_K = ifft(S_gamma);
    r_K = [c_K(1); c_K(end:-1:2)];
    K_mat = toeplitz(c_K, r_K);

    % Separate the nonlocal matrix into purely real and imaginary arrays
    K_R = real(K_mat); K_I = imag(K_mat);

    % Form the real and imaginary parts of the continuous Floquet operator L_gamma
    % L_gamma = L_R + i*L_I 
    LR = D * D2 - D * gamma(j)^2 * I_mat + V_mat - U0_mat * K_R;
    LI = 2 * D * gamma(j) * D1 - U0_mat * K_I;

    % Assemble the purely real-valued 2Nx2N block matrix
    % Maps the complex state w = w_R + i w_I into a stacked real vector [w_R; w_I]
    A_block = [LR, -LI; LI,  LR];

    % Solve the purely real-valued eigenvalue problem
    evals = eig(A_block);

    % Sort by the largest real growth rate for consistent spectrum tracking
    [~, idx] = sort(real(evals), 'descend');
    evs(:, j) = -evals(idx);
end

if plotflag
    plot(gamma,real(evs(1,:)),'k','linewidth',1.4)
    xlabel('$\gamma$','interpreter','latex')
    ylabel('Min eigenvalue')
    max_eig = min(real(evs(1,:)));
    title(sprintf('D = %.0e, $\\lambda$ = %.3g, Growth rate = %.2g', D, wl,-max_eig),'interpreter','latex')
    set(gca,'FontSize',18)
    grid on
    drawnow
end